import { GoogleGenAI } from "@google/genai";

/**
 * Provides smart suggestions based on the provided system context.
 * Re-initializes GoogleGenAI within the function for safety.
 */
export async function getSmartSuggestion(context: string): Promise<string> {
  const apiKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;

  if (!apiKey) {
    console.warn("Gemini API key is not configured.");
    return "Surveillance systems operational. Proceed with standard patrol protocols.";
  }

  try {
    const ai = new GoogleGenAI({ apiKey });

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Context: You are an AI security advisor for a drone fleet management system. 
      System state: ${context}. 
      Provide a concise (2 sentences) strategic suggestion.`,
      config: {
        temperature: 0.7,
        topP: 0.9
      }
    });

    return response.text || "Perimeter clear. Maintain current readiness level.";
  } catch (error) {
    console.error("Gemini Suggestion Error:", error);
    return "System optimal. Analyzing localized heatmaps for potential route optimization.";
  }
}

