                      <span className="material-symbols-outlined text-[18px] text-primary">flight</span> Active Drones
                    </h4>
                    <div className="flex flex-wrap gap-3">
                      {selectedRoute.drones.length > 0 ? selectedRoute.drones.map(d => (
