      case 'P1': return 'bg-[#FF4B4B] text-white';
      case 'P2': return 'bg-[#FF9F43] text-black';
      case 'P3': return 'bg-[#FFC857] text-black';
      case 'P4': return 'bg-[#2ECC71]/20 text-[#2ECC71]';
      default: return 'bg-gray-700 text-gray-300';
